def compute(vars):
    operating_expenses = vars["v1"]
    net_interest_revenue = vars["v2"]

    if net_interest_revenue == 0:
        return None

    ratio = operating_expenses / net_interest_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_expenses": operating_expenses,
            "net_interest_revenue": net_interest_revenue,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
